{"command":"python3 << 'PY'
import subprocess, json
def run(inp, args=[]):
    return subprocess.run(["./executable"]+args, input=inp.encode() if isinstance(inp,str) else inp, capture_output=True)
def test_field(container_template, field):
    # returns error or OK for wrong type tests
    results={}
    for val_desc,val in [("num",12345),("str","zzz"),("bool",True),("obj",{"x":1}),("arr",["a"])]:
        obj=json.loads(json.dumps(container_template))  # copy
        # Navigate??? Simplistic: we'll construct outside
        results[val_desc]=val
    return results

candidates=["Err","Error","Message","Msg","Text","GoMod","Dir","Path","Version","Time","Update","Main","Indirect","Query","Replaced","Sum","Hash","GoVersion","Retracted","Deprecated","Require","Exclude","Replace","Indirect","Licenses","VCS","URL","Zip","Info","Mod","Canonical","Local","IsDir","IsFile","Origin","Reuse","Validated","Version2","Selected","Incomplete","Vendor","CommandLine"]

def probe_outer(field):
    outs=[]
    for val in [12345,"zzz",True,{"X":1},["a"],[123]]:
        obj={"Path":"a.com/x","Version":"v1",field:val}
        inp=json.dumps(obj)+"\n"
        p=run(inp)
        err=p.stderr.decode().strip()
        if err:
            err=err.split(" ",2)[2] if len(err.split(" ",2))>2 else err
            outs.append(err)
        else:
            outs.append("OK")
    # if any not OK, print
    if any(o!="OK" for o in outs):
        print(field, outs)

print("Outer extra candidates:")
for c in candidates:
    probe_outer(c)
print("done outer")

# Error subfields
print("\nError nested:")
err_candidates=["Err","Error","Message","Msg","Text","Path","Version","Query","Info","Stack","Code","Name","Type","Description","Detail","Summary","Cause"]
for field in err_candidates:
    outs=[]
    for val in [12345,"zzz",True,{"X":1},["a"]]:
        obj={"Path":"a.com/x","Version":"v1","Error":{field:val}}
        p=run(json.dumps(obj)+"\n")
        err=p.stderr.decode().strip()
        if err:
            err=err.split(" ",2)[2] if len(err.split(" ",2))>2 else err
            outs.append(err)
        else:
            outs.append("OK")
    if any(o!="OK" for o in outs):
        print(field, outs)
print("done error nested")

# Also test Error with null etc
for val in [None,{}, {"Err":"boom"}, {"Err":"boom","Other":123}]:
    obj={"Path":"a.com/x","Version":"v1","Error":val}
    p=run(json.dumps(obj)+"\n")
    print("Error val",val,"exit",p.returncode,"stdout",repr(p.stdout.decode()),"stderr",repr(p.stderr.decode()))

# Replace behaviour: does Replace affect output? Path/Version displayed maybe replaced?
print("\nReplace effect:")
for repl in [None,{}, {"Path":"replaced.com/y","Version":"v9"}, {"Path":"repl","Version":"v9","Time":"2021-01-01T00:00:00Z"}]:
    obj={"Path":"a.com/x","Version":"v1","Replace":repl}
    p=run(json.dumps(obj)+"\n")
    print(repl, repr(p.stdout.decode()))

PY
"}

