{"command":"python3 << 'PY'
import subprocess, json
def run(inp, args=[]):
    return subprocess.run(["./executable"]+args, input=inp.encode() if isinstance(inp,str) else inp, capture_output=True)
def show(desc,obj,args=[]):
    p=run(json.dumps(obj)+"\n",args)
    print(f"=== {desc} args={args} exit={p.returncode}")
    print(p.stdout.decode(), end='')
    if p.stderr: print("STDERR:",p.stderr.decode()[:2000])

# Base
base={"Path":"a.com/x","Version":"v1","Time":"2020-01-01T00:00:00Z","Update":{"Path":"a.com/x","Version":"v2","Time":"2021-01-01T00:00:00Z"}}

# Replace with diff version/time/etc
obj=dict(base); obj["Replace"]={"Path":"repl.com/y","Version":"v9","Time":"2019-01-01T00:00:00Z"}
show("Replace time 2019 (before orig, before update) base times valid",obj)

obj=dict(base); obj["Replace"]={"Path":"repl.com/y","Version":"v9","Time":"2022-01-01T00:00:00Z"}
show("Replace time 2022 (after update 2021) - if effective time=replace, invalid => valid false",obj)

obj=dict(base); obj["Replace"]={"Path":"repl.com/y","Version":"v9"}  # no replace time
show("Replace no time - if time overwritten with nil, valid true and no panic; if orig time retained, valid (?) update time present so true anyway",obj)

# Distinguish panic: orig Time present, Update Time missing => panic normally. If Replace overwrites Time with its Time (present or nil) what happens?
obj2={"Path":"a.com/x","Version":"v1","Time":"2020-01-01T00:00:00Z","Update":{"Path":"a.com/x","Version":"v2"}} # no update time => panic base
show("base panic check",obj2)
obj=dict(obj2); obj["Replace"]={"Version":"v9","Time":"2019-01-01T00:00:00Z"}
show("panic base + Replace with time",obj)
obj=dict(obj2); obj["Replace"]={"Version":"v9"}  # no time
show("panic base + Replace no time (if time becomes nil, no panic)",obj)

# Update inside replace
obj={"Path":"a.com/x","Version":"v1","Update":{"Path":"a.com/x","Version":"v2"},"Replace":{"Version":"v9","Update":{"Version":"vREPLUPD"}}}
show("Replace.Update version",obj)

obj={"Path":"a.com/x","Version":"v1","Replace":{"Version":"v9","Update":{"Version":"vREPLUPD","Time":"2021-01-01T00:00:00Z"}}}
show("Only Replace.Update (no top Update)",obj)
show("Only Replace.Update with -update filter",obj,["-update"])
show("Only Replace.Update with -ci",obj,["-ci"])

# Replace Indirect/Main
obj={"Path":"a.com/x","Version":"v1","Indirect":False,"Replace":{"Version":"v9","Indirect":True}}
show("Replace Indirect true, orig false",obj)
show(".. -direct",obj,["-direct"])
obj={"Path":"a.com/x","Version":"v1","Indirect":True,"Replace":{"Version":"v9","Indirect":False}}
show("Replace Indirect false, orig true",obj)
show(".. -direct",obj,["-direct"])

obj={"Path":"a.com/x","Version":"v1","Main":False,"Replace":{"Version":"v9","Main":True}}
show("Replace Main true",obj)
obj={"Path":"a.com/x","Version":"v1","Main":True,"Replace":{"Version":"v9","Main":False}}
show("Orig Main true, Replace Main false",obj)

# Update.Replace
obj={"Path":"a.com/x","Version":"v1","Update":{"Version":"v2","Replace":{"Version":"vUPDREPL"}}}
show("Update.Replace version",obj)

# Replace.Replace
obj={"Path":"a.com/x","Version":"v1","Replace":{"Version":"v9","Replace":{"Version":"vNN"}}}
show("Replace.Replace",obj)

# Path from replace if original empty
obj={"Version":"v1","Replace":{"Path":"repl/path","Version":"v9"}}
show("Orig path empty, replace path",obj)

PY
"}

