import json, math, itertools
data=json.load(open("/tmp/wrapdata.json"))

def line_len(lens,i,j): # words i:j exclusive
    return sum(lens[i:j]) + (j-i-1) if j>i else 0

def dp(lens, lim=30, exp=2, tie='first_small', last_free=True, pen_per_line=0, overflow='inf'):
    n=len(lens)
    # DP from end: dp[i]= min cost to wrap i:n, choice next break j
    INF=10**18
    cost=[0]*(n+1); choice=[n]*(n+1)
    # cost[n]=0
    for i in range(n-1,-1,-1):
        best=INF; bestj=None
        js = range(i+1,n+1)
        if tie in ('last_small',): # choose smallest j when tie? iterate and update with <= maybe
            pass
        for j in js:
            ll=line_len(lens,i,j)
            if ll>lim:
                if j==i+1 and overflow=='allow':
                    lc=0
                else:
                    # as words positive, further j only larger (if widths >=0), break
                    if j>i+1: break
                    else: continue
            else:
                if j==n and last_free:
                    lc=0
                else:
                    slack=lim-ll
                    lc=(slack**exp)+pen_per_line
            total=lc+cost[j]
            # tie policy starting with ascending j
            if tie=='first_small':
                if total<best:
                    best=total; bestj=j
            elif tie=='first_large': # prefer larger j (last encountered) on tie
                if total<=best:
                    best=total; bestj=j
            else: raise
        cost[i]=best; choice[i]=bestj
    parts=[]; i=0
    while i<n:
        j=choice[i]
        if j is None: break
        parts.append(lens[i:j]); i=j
    return parts

def dp_forward(lens,lim=30,exp=2,tie='first',last_free=True,pen=0):
    # DP computing cost to reach i, with last line special handled difficult (need total); not use.
    pass

def greedy(lens,lim=30, direction='forward'):
