            if cur and cur_len+add>lim:
                parts.append(cur); cur=[l]; cur_len=l
            else:
                cur.append(l); cur_len+=add
        if cur: parts.append(cur)
        return parts
    else:
        # reverse greedy then reverse segments
        parts=[]; cur=[]; cur_len=0
        for l in reversed(lens):
            add=l if not cur else l+1
            if cur and cur_len+add>lim:
                parts.append(list(reversed(cur))); cur=[l]; cur_len=l
            else:
                cur.append(l); cur_len+=add
        if cur: parts.append(list(reversed(cur)))
        return list(reversed(parts))

models={}
for exp in [1,2,3,4]:
    for tie in ['first_small','first_large']:
