package mod

import (
	"encoding/json"
	"io"
	"time"
)

// ModuleError describes an error returned for a module.
type ModuleError struct {
	Err string
}

// Module is a single entry in the JSON stream produced by
// "go list -u -m -json all".
type Module struct {
	Path      string
	Version   string
	Versions  []string
	Replace   *Module
	Time      *time.Time
	Update    *Module
	Main      bool
	Indirect  bool
	Dir       string
	GoMod     string
	GoVersion string
	Error     *ModuleError
}

// Parse decodes a stream of JSON module objects. Decoding stops at EOF;
// any other decoding error is returned to the caller.
func Parse(in io.Reader) ([]Module, error) {
	decoder := json.NewDecoder(in)
	modules := []Module{}

	for {
		var module Module
		err := decoder.Decode(&module)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		modules = append(modules, module)
	}

	return modules, nil
}

func (m *Module) effectiveModule() *Module {
	if m.Replace != nil {
		return m.Replace
	}
	return m
}

// ResolvedVersion returns the version in effect for display. A replacement
// module, when present, supplies that version.
func (m *Module) ResolvedVersion() string {
	return m.effectiveModule().Version
}

// HasUpdate reports whether the effective module has an update.
func (m *Module) HasUpdate() bool {
	return m.effectiveModule().Update != nil
}

// NewVersion returns the version of the effective update, if any.
func (m *Module) NewVersion() string {
	effective := m.effectiveModule()
	if effective.Update != nil {
		return effective.Update.Version
	}
	return ""
}

// Direct reports whether the module is a direct dependency.
func (m *Module) Direct() bool {
	return !m.Indirect
}

// InvalidTimestamp reports whether the effective module's own timestamp is
// later than the timestamp of its available update.
func (m *Module) InvalidTimestamp() bool {
	effective := m.effectiveModule()
	if effective.Time == nil || effective.Update == nil {
		return false
	}
	return effective.Time.After(*effective.Update.Time)
}
EOF

