package runner

import (
	"io"
	"log"
	"os"
	"strconv"

	"github.com/psampaz/go-mod-outdated/internal/mod"
)

// Run reads module JSON from in, writes the resulting table to out, and
// applies the update, direct and ci filters.
func Run(in io.Reader, out io.Writer, update, direct, ci bool, style string) {
	modules, err := mod.Parse(in)
	if err != nil {
		log.Println(err)
		return
	}

	filtered := make([]mod.Module, 0, len(modules))
	for _, module := range modules {
		if module.Main {
			continue
		}
		if direct && module.Indirect {
			continue
		}
		if update && module.Update == nil {
			continue
		}
		filtered = append(filtered, module)
	}

	if len(filtered) == 0 {
		return
	}

	renderTable(out, filtered, style)

	if ci {
		for i := range filtered {
			if filtered[i].HasUpdate() {
				os.Exit(1)
			}
		}
	}
}

func renderTable(out io.Writer, modules []mod.Module, style string) {
	t := newTable([]string{"MODULE", "VERSION", "NEW VERSION", "DIRECT", "VALID TIMESTAMPS"})

	for i := range modules {
		module := &modules[i]
		t.append([]string{
			module.Path,
			module.ResolvedVersion(),
			module.NewVersion(),
			strconv.FormatBool(module.Direct()),
			strconv.FormatBool(!module.InvalidTimestamp()),
		})
	}

	t.render(out, style == "markdown")
}
