{"command":"cat > internal/runner/table.go <<'EOF'
package runner

import (
	"io"
	"math"
	"strings"
)

const maxColumnContentWidth = 30

type table struct {
	headers []string
	widths  []int
	rows    [][]processedCell
}

type processedCell struct {
	lines []string
}

func newTable(headers []string) *table {
	t := &table{headers: headers, widths: make([]int, len(headers))}
	for i, header := range headers {
		t.widths[i] = displayWidth(header)
	}
	return t
}

func (t *table) append(row []string) {
	processed := make([]processedCell, len(row))
	for i, cell := range row {
		lines, contribution := processCell(cell)
		processed[i] = processedCell{lines: lines}
		if contribution > t.widths[i] {
			t.widths[i] = contribution
		}
	}
	t.rows = append(t.rows, processed)
}

func (t *table) render(out io.Writer, markdown bool) {
	if !markdown {
		writeLine(out, t.borderLine())
	}
	writeLine(out, t.headerLine())
	if markdown {
		writeLine(out, t.markdownSeparatorLine())
	} else {
		writeLine(out, t.borderLine())
	}
	for _, row := range t.rows {
		for _, line := range t.rowLines(row) {
			writeLine(out, line)
		}
	}
	if !markdown {
		writeLine(out, t.borderLine())
	}
}

func writeLine(out io.Writer, line string) {
	_, _ = io.WriteString(out, line+"\n")
}

func (t *table) borderLine() string {
	var b strings.Builder
	b.WriteByte('+')
	for _, width := range t.widths {
		b.WriteString(strings.Repeat("-", width+2))
		b.WriteByte('+')
	}
	return b.String()
}

func (t *table) markdownSeparatorLine() string {
	var b strings.Builder
	b.WriteByte('|')
	for _, width := range t.widths {
		b.WriteString(strings.Repeat("-", width+2))
		b.WriteByte('|')
	}
	return b.String()
}

func (t *table) headerLine() string {
	var b strings.Builder
	b.WriteByte('|')
	for i, header := range t.headers {
		total := t.widths[i] + 2
		headerWidth := displayWidth(header)
		left := (total - headerWidth) / 2
		if left < 0 {
			left = 0
		}
		right := total - headerWidth - left
		if right < 0 {
			right = 0
		}
		b.WriteString(strings.Repeat(" ", left))
		b.WriteString(header)
		b.WriteString(strings.Repeat(" ", right))
		b.WriteByte('|')
	}
	return b.String()
}

func (t *table) rowLines(row []processedCell) []string {
	lineCount := 0
	for _, cell := range row {
		if len(cell.lines) > lineCount {
			lineCount = len(cell.lines)
		}
	}

	lines := make([]string, 0, lineCount)
	for lineIndex := 0; lineIndex < lineCount; lineIndex++ {
		var b strings.Builder
		b.WriteByte('|')
		for column, cell := range row {
			text := ""
			if lineIndex < len(cell.lines) {
				text = cell.lines[lineIndex]
			}
			padding := t.widths[column] - displayWidth(text) + 1
			if padding < 1 {
				padding = 1
			}
			b.WriteByte(' ')
			b.WriteString(text)
			b.WriteString(strings.Repeat(" ", padding))
			b.WriteByte('|')
		}
		lines = append(lines, b.String())
	}
	return lines
}

func processCell(text string) ([]string, int) {
	widest := 0
	for _, line := range strings.Split(text, "\n") {
		if width := displayWidth(line); width > widest {
			widest = width
		}
	}

	limit := widest
	if limit > maxColumnContentWidth {
		limit = maxColumnContentWidth
	}

	lines := wrapString(text, limit)

	contribution := limit
	for _, line := range lines {
		if width := displayWidth(line); width > contribution {
			contribution = width
		}
	}
	return lines, contribution
}

func wrapString(text string, limit int) []string {
	words := strings.Split(strings.ReplaceAll(text, "\n", " "), " ")
	widths := make([]int, len(words))
	for i, word := range words {
		widths[i] = stringWidth(word)
		if widths[i] > limit {
			limit = widths[i]
		}
	}
	return wrapWords(words, widths, limit)
}

// wrapWords lays out words with a minimum-raggedness dynamic program. Every
// line except the final one contributes the square of its unused width to
// the total cost. When costs tie, the earliest suitable break is retained
// because successor positions are examined in increasing order.
func wrapWords(words []string, widths []int, limit int) []string {
	n := len(words)
	if n == 0 {
		return []string{""}
	}

	prefix := make([]int, n+1)
	for i, width := range widths {
		prefix[i+1] = prefix[i] + width
	}

	cost := make([]int64, n+1)
	next := make([]int, n)
	cost[n] = 0

	for i := n - 1; i >= 0; i-- {
		best := int64(math.MaxInt64)
		bestNext := i + 1
		for j := i + 1; j <= n; j++ {
			lineWidth := prefix[j] - prefix[i] + (j - i - 1)
			if lineWidth > limit {
				break
			}

			var lineCost int64
			if j < n {
				slack := int64(limit - lineWidth)
				lineCost = slack * slack
			}
			total := lineCost + cost[j]
			if total < best {
				best = total
				bestNext = j
			}
		}
		cost[i] = best
		next[i] = bestNext
	}

	lines := []string{}
	for i := 0; i < n; {
		j := next[i]
		if j <= i || j > n {
			j = i + 1
		}
		lines = append(lines, strings.Join(words[i:j], " "))
		i = j
	}
	return lines
}
