package runner

import (
	"regexp"
	"sort"
	"unicode"
)

var ansiEscape = regexp.MustCompile("\x1b\\[(?:[0-9]{1,3}(?:;[0-9]{1,3})*)?[m|K]")

// displayWidth is the cell-measurement width: conventional ANSI colour and
// erase sequences are removed before the remaining text is measured.
func displayWidth(s string) int {
	return stringWidth(ansiEscape.ReplaceAllString(s, ""))
}

// stringWidth measures a string as a sum of grapheme-cluster widths. The
// width of a cluster is taken from its first rune.
func stringWidth(s string) int {
	if s == "" {
		return 0
	}
	runes := []rune(s)
	width := 0
	for start := 0; start < len(runes); {
		end := nextGraphemeCluster(runes, start)
		if end <= start {
			end = start + 1
		}
		width += runeWidth(runes[start])
		start = end
	}
	return width
}

func runeWidth(r rune) int {
	if r <= 0 {
		return 0
	}
	if r < 0x20 || (r >= 0x7f && r < 0xa0) {
		return 0
	}
	if isWideRune(r) {
		return 2
	}
	if isZeroWidthRune(r) {
		return 0
	}
	return 1
}

func isWideRune(r rune) bool {
	index := sort.Search(len(wideRanges), func(i int) bool {
		return wideRanges[i].hi >= r
	})
	return index < len(wideRanges) && wideRanges[index].lo <= r
}

func isZeroWidthRune(r rune) bool {
	switch {
	case r == 0x00ad, r == 0x180e, r == 0x2028, r == 0x2029, r == 0xfeff:
		return true
	case r >= 0x200b && r <= 0x200f:
		return true
	case r >= 0x202a && r <= 0x202e:
		return true
	case r >= 0x206a && r <= 0x206f:
		return true
	case r >= 0xfff9 && r <= 0xfffb:
		return true
	case r >= 0xfe00 && r <= 0xfe0f:
		// Variation selectors measure as ordinary runes when they start
		// a grapheme cluster.
		return false
	case r >= 0xe0100 && r <= 0xe01ef:
		return false
	case r == 0x17b4 || r == 0x17b5:
		return false
	}
	return unicode.In(r, unicode.Mn, unicode.Me)
}

const (
	graphemeOther = iota
	graphemeControl
	graphemeCR
	graphemeLF
	graphemeExtend
	graphemeZWJ
	graphemeSpacingMark
	graphemePrepend
	graphemeHangulL
	graphemeHangulV
	graphemeHangulT
	graphemeHangulLV
	graphemeHangulLVT
	graphemeRegionalIndicator
)

func nextGraphemeCluster(runes []rune, start int) int {
	regionalIndicators := 0
	if graphemeClass(runes[start]) == graphemeRegionalIndicator {
		regionalIndicators = 1
	}

	for i := start + 1; i < len(runes); i++ {
		if graphemeBreakBetween(runes, start, i, regionalIndicators) {
			return i
		}
		if graphemeClass(runes[i]) == graphemeRegionalIndicator {
			regionalIndicators++
		}
	}
	return len(runes)
}

func graphemeBreakBetween(runes []rune, clusterStart, i, regionalIndicators int) bool {
	previous := graphemeClass(runes[i-1])
	current := graphemeClass(runes[i])

	if previous == graphemeCR && current == graphemeLF {
		return false
	}
	if previous == graphemeControl || previous == graphemeCR || previous == graphemeLF {
		return true
	}
	if current == graphemeControl || current == graphemeCR || current == graphemeLF {
		return true
	}

	// Hangul syllable sequences.
	if previous == graphemeHangulL &&
		(current == graphemeHangulL || current == graphemeHangulV ||
			current == graphemeHangulLV || current == graphemeHangulLVT) {
		return false
	}
	if (previous == graphemeHangulLV || previous == graphemeHangulV) &&
		(current == graphemeHangulV || current == graphemeHangulT) {
		return false
	}
	if (previous == graphemeHangulLVT || previous == graphemeHangulT) &&
		current == graphemeHangulT {
		return false
	}

	if current == graphemeExtend || current == graphemeZWJ || current == graphemeSpacingMark {
		return false
	}
	if previous == graphemePrepend {
		return false
	}

	// Extended grapheme clusters joined by a zero-width joiner after an
	// extended pictographic code point.
	if previous == graphemeZWJ && isExtendedPictographic(runes[i]) &&
		hasExtendedPictographicBeforeZWJ(runes, clusterStart, i-1) {
		return false
	}

	// Regional indicators form pairs.
	if previous == graphemeRegionalIndicator && current == graphemeRegionalIndicator &&
		regionalIndicators%2 == 1 {
		return false
	}

	return true
}

func hasExtendedPictographicBeforeZWJ(runes []rune, clusterStart, zwjIndex int) bool {
	for i := zwjIndex - 1; i >= clusterStart; i-- {
		if graphemeClass(runes[i]) == graphemeExtend {
			continue
		}
		return isExtendedPictographic(runes[i])
	}
	return false
}

func graphemeClass(r rune) int {
	switch {
	case r == '\r':
		return graphemeCR
	case r == '\n':
		return graphemeLF
	case r == 0x200d:
		return graphemeZWJ
	case r == 0x200c:
		return graphemeExtend
	case r >= 0x1f3fb && r <= 0x1f3ff:
		return graphemeExtend
	case r >= 0xe0020 && r <= 0xe007f:
		return graphemeExtend
	case isPrependRune(r):
		return graphemePrepend
	case (r >= 0x1100 && r <= 0x115f) || (r >= 0xa960 && r <= 0xa97c):
		return graphemeHangulL
	case (r >= 0x1160 && r <= 0x11a7) || (r >= 0xd7b0 && r <= 0xd7c6):
		return graphemeHangulV
	case (r >= 0x11a8 && r <= 0x11ff) || (r >= 0xd7fb && r <= 0xd7ff):
		return graphemeHangulT
	case r >= 0xac00 && r <= 0xd7a3:
		if (r-0xac00)%28 == 0 {
			return graphemeHangulLV
		}
		return graphemeHangulLVT
	case r >= 0x1f1e6 && r <= 0x1f1ff:
		return graphemeRegionalIndicator
	case unicode.In(r, unicode.Mn, unicode.Me):
		return graphemeExtend
	case unicode.In(r, unicode.Mc):
		return graphemeSpacingMark
	case unicode.In(r, unicode.Cc, unicode.Cf, unicode.Zl, unicode.Zp):
		return graphemeControl
	default:
		return graphemeOther
	}
}

func isPrependRune(r rune) bool {
	switch {
	case r >= 0x0600 && r <= 0x0605:
		return true
	case r >= 0x0890 && r <= 0x0891:
		return true
	case r >= 0x111c2 && r <= 0x111c5:
		return true
	case r >= 0x11d90 && r <= 0x11d91:
		return true
	}
	switch r {
	case 0x06dd, 0x070f, 0x08e2, 0x0d4e, 0x110bd, 0x110cd, 0x111c9, 0x11a47, 0x1e2ae:
		return true
	}
	return false
}

func isExtendedPictographic(r rune) bool {
	if r >= 0x1f1e6 && r <= 0x1f1ff {
		return false
	}
	switch {
	case r >= 0x1f000 && r <= 0x1faff:
		return true
	case r >= 0x2300 && r <= 0x23ff:
		return true
	case r >= 0x2600 && r <= 0x27bf:
		return true
	case r >= 0x2b00 && r <= 0x2bff:
		return true
	case r >= 0x2194 && r <= 0x2199:
		return true
	case r >= 0x21a9 && r <= 0x21aa:
		return true
	case r >= 0x2934 && r <= 0x2935:
		return true
	}
	switch r {
	case 0x00a9, 0x00ae, 0x203c, 0x2049, 0x2122, 0x2139, 0x3030, 0x303d, 0x3297, 0x3299:
		return true
	}
	return false
}
