    c=chr(cp)
    rows.append((cp,cp in diff,unicodedata.category(c),unicodedata.east_asian_width(c),unicodedata.combining(c),unicodedata.bidirectional(c)))
from collections import Counter,defaultdict
for key_idx,name in [(2,'cat'),(3,'eaw'),(4,'comb'),(5,'bidi')]:
